using namespace std;
using ll = long long;
const int N = 10;
string maze[N];
int scientists[N][N] = {};
int rescue[N][N] = {};
int infect_time[N][N] = {};
int dir_i[] = {-1, 1, 0, 0};
int dir_j[] = {0, 0, -1, 1};
int reach[N][N][N][N] = {};
const int MAX_FLOW = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj[MAX_FLOW+1];
int cap[MAX_FLOW][MAX_FLOW], flow[MAX_FLOW][MAX_FLOW], ptr[MAX_FLOW], dist[MAX_FLOW], parent[MAX_FLOW];

bool build_graph(int s, int t) {
    memset(dist, -1, sizeof dist);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(auto v : adj[u]) {
            if(cap[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[t] != -1;
}

bool dfs_search(int u, int t) {
    if(u == t) return true;
    for(int& i = ptr[u]; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if(dist[v] == dist[u] + 1 && cap[u][v] - flow[u][v] > 0 && dfs_search(v, t)) {
            parent[v] = u;
            return true;
        }
    }
    return false;
}

bool find_path(int s, int t) {
    memset(parent, -1, sizeof parent);
    parent[s] = 0;
    return dfs_search(s, t);
}

void setup_network() {
    memset(cap, 0, sizeof cap);
    memset(flow, 0, sizeof flow);
}

void add_network_edge(int u, int v, int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    cap[u][v] += c;
}

int max_flow(int s, int t) {
    int total = 0;
    while(build_graph(s, t)) {
        memset(ptr, 0, sizeof ptr);
        while(find_path(s, t)) {
            int min_cap = INF;
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                min_cap = min(min_cap, cap[u][v] - flow[u][v]);
            }
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                flow[u][v] += min_cap;
                flow[v][u] -= min_cap;
            }
            total += min_cap;
        }
    }
    return total;
}

int node_id(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}

