                infect_time[ni][nj] = infect_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
    memset(reach, -1, sizeof reach);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(maze[i][j] == '.') {
                reach[i][j][i][j] = 0;
                queue<pair<int,int>> q2;
                q2.push({i,j});
                while(!q2.empty()) {
